#!/usr/bin/env python3
"""Merge user data from three heterogeneous sources into one parquet + conflict report."""
import csv
import json
import os
from datetime import datetime, date

import pandas as pd

SOURCE_A = "/data/source_a/users.json"
SOURCE_B = "/data/source_b/users.csv"
SOURCE_C = "/data/source_c/users.parquet"
OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

FIELD_MAP = {
    "user_id": "user_id", "id": "user_id", "userid": "user_id", "user id": "user_id",
    "email": "email", "email_address": "email", "emailaddress": "email", "mail": "email",
    "full_name": "name", "name": "name", "username": "name", "user_name": "name",
    "fullname": "name",
    "registration_date": "created_date", "created_at": "created_date", "joined": "created_date",
    "createddate": "created_date", "created_date": "created_date", "join_date": "created_date",
    "status": "status", "is_active": "status", "active": "status", "isactive": "status",
}

DATE_FORMATS = [
    "%Y-%m-%d", "%Y/%m/%d", "%d/%m/%Y", "%m/%d/%Y", "%d-%m-%Y", "%m-%d-%Y",
    "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%d %b %Y", "%d %B %Y", "%b %d, %Y",
    "%B %d, %Y", "%Y%m%d",
]


def norm_key(k):
    return FIELD_MAP.get(str(k).strip().lower().replace(" ", "_"))


def norm_date(v):
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    if isinstance(v, (datetime, date)):
        return v.strftime("%Y-%m-%d")
    if isinstance(v, pd.Timestamp):
        return v.strftime("%Y-%m-%d")
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "null", "nat"):
        return None
    if s.isdigit() and len(s) == 10:  # unix seconds
        try:
            return datetime.utcfromtimestamp(int(s)).strftime("%Y-%m-%d")
        except (ValueError, OverflowError):
            pass
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    try:
        ts = pd.to_datetime(s, errors="raise")
        return pd.Timestamp(ts).strftime("%Y-%m-%d")
    except Exception:
        return s


def norm_status(v):
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    low = s.lower()
    if low in ("true", "1", "yes", "y", "t"):
        return "active"
    if low in ("false", "0", "no", "n", "f"):
        return "inactive"
    return s


def norm_text(v):
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    return s


def norm_record(raw):
    rec = {}
    for k, v in raw.items():
        f = norm_key(k)
        if f is None:
            continue
        if f == "user_id":
            try:
                rec[f] = int(float(str(v).strip()))
            except (TypeError, ValueError):
                rec[f] = None
        elif f == "created_date":
            rec[f] = norm_date(v)
        elif f == "status":
            rec[f] = norm_status(v)
        else:
            rec[f] = norm_text(v)
    return rec


def load_json(path):
    if not os.path.exists(path):
        return []
    with open(path) as fh:
        data = json.load(fh)
    if isinstance(data, dict):
        for key in ("users", "data", "records"):
            if key in data and isinstance(data[key], list):
                data = data[key]
                break
        else:
            data = [data]
    return [norm_record(r) for r in data if isinstance(r, dict)]


def load_csv(path):
    if not os.path.exists(path):
        return []
    with open(path, newline="") as fh:
        return [norm_record(r) for r in csv.DictReader(fh)]


def load_parquet(path):
    if not os.path.exists(path):
        return []
    df = pd.read_parquet(path)
    out = []
    for raw in df.to_dict("records"):
        out.append(norm_record({k: (None if (not isinstance(v, (list, dict)) and pd.isna(v)) else v)
                                for k, v in raw.items()}))
    return out


def main():
    sources = [
        ("source_a", load_json(SOURCE_A)),
        ("source_b", load_csv(SOURCE_B)),
        ("source_c", load_parquet(SOURCE_C)),
    ]

    # user_id -> {source: record}, preserving first-seen order
    per_user = {}
    for sname, records in sources:
        for rec in records:
            uid = rec.get("user_id")
            if uid is None:
                continue
            per_user.setdefault(uid, {})
            if sname not in per_user[uid]:
                per_user[uid][sname] = rec

    priority = ["source_a", "source_b", "source_c"]
    fields = ["name", "email", "created_date", "status"]

    merged_rows = []
    conflicts = []

    for uid in sorted(per_user):
        by_src = per_user[uid]
        row = {"user_id": int(uid)}
        for field in fields:
            values = {}
            for s in priority:
                if s in by_src:
                    v = by_src[s].get(field)
                    if v is not None:
                        values[s] = v
            selected = None
            for s in priority:
                if s in values:
                    selected = values[s]
                    break
            row[field] = selected
            if len(set(values.values())) > 1:
                conflicts.append({
                    "user_id": int(uid),
                    "field": field,
                    "values": {s: values[s] for s in priority if s in values},
                    "selected": selected,
                })
        merged_rows.append(row)

    df = pd.DataFrame(merged_rows, columns=["user_id", "name", "email", "created_date", "status"])
    df["user_id"] = df["user_id"].astype("int64")
    for col in ("name", "email", "created_date", "status"):
        df[col] = df[col].astype(object).where(df[col].notna(), None).astype("string")
    df.to_parquet(OUT_PARQUET, index=False)

    with open(OUT_CONFLICTS, "w") as fh:
        json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, fh, indent=2)

    print(df)
    print("conflicts:", len(conflicts))


if __name__ == "__main__":
    main()
